    for pivots in itertools.combinations(range(n),d):
        # free positions for each row: positions > pivot that are not pivots
        frees=[[j for j in range(p+1,n) if j not in pivots] for p in pivots]
        for vals in itertools.product(*[range(1<<len(f)) for f in frees]):
