import json,sys
r=json.load(open('/work/trace.json'))['rows']
fm=sys.argv[1] if len(sys.argv)>1 else 'after'
def touch(b,w):
    b[0]= 0 if w>=2 else 1   # b0=1 -> victim right? define: b0 points to victim side (0 left,1 right)
    if w<2: b[1]= 1-w
    else: b[2]= 1-(w-2)
def victim(b):
    return b[1] if b[0]==0 else 2+b[2]
def fresh(): return [[None]*4 for _ in range(8)],[[0,0,0] for _ in range(8)]
tags,bits=fresh(); errs=0; out=None
for k,(rst,req,fl,a,h) in enumerate(r):
    if out is not None and h!='x' and out!=h:
        errs+=1; print('ERR',k,'dev',h,'model',out, 'prev row',r[k-1])
    if rst: tags,bits=fresh(); out=0; continue
    o=0
    if req:
        s=(a>>1&1)|(a>>2&1)<<1|(a>>5&1)<<2; t=a>>1
        T=tags[s]
        if t in T: o=1; touch(bits[s],T.index(t))
        else:
            if None in T: w=T.index(None)
            else: w=victim(bits[s])
            if not (fl and fm=='nofill'):
                T[w]=t; touch(bits[s],w)
    if fl:
        if fm in('after','nofill'): tags,bits=fresh()
        elif fm=='validonly': tags=[[None]*4 for _ in range(8)]
    out=o
print('errs',errs)
